sp_widget.client_script:
api.controller = function (DHManagerService, $scope) {
	var c = this;

	c.devices = null;
	c.userAssets = [];
	c.assetsExist = false;
	c.loading = true;
	c.state = DHManagerService.state;
	c.loaded = false;

	$scope.$watch( () => DHManagerService.state.assetsLoading, (loading) => c.loading = loading);

	if (c.data.selectedDevice) {
		c.selectDevice(c.data.selectedDevice);
	}

	c.$onInit = function() {
		DHManagerService.getMetrics().then((r) => {
			c.devices = r;
			c.loaded = true;
		});
	};

	c.getSelectedAsset = function () {
		return DHManagerService.selectedAsset;
	};

	c.selectDevice = function (assetID) {
		DHManagerService.setSelectedAsset(assetID);
	};

	c.handleKeyDown = function (event, assetID) {
		if (event.key === "Enter") {
			DHManagerService.setSelectedAsset(assetID);
		}
	};


};

sp_widget.css:
.device-picker {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
}

.loading {
  min-height: 4rem;
  width: 100%;
  border-radius: 1rem;
  background: #f6f7f8;
  background-image: linear-gradient(to right, #f6f7f8 0%, #edeef1 20%, #f6f7f8 40%, #f6f7f8 100%);
  background-repeat: no-repeat;
  background-size: 100rem 28rem;
  animation: shimmer 2s infinite linear;
}

.device {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: nowrap;
  border-radius: .7rem;
  border: 1px solid #D9D9D9;

  &:hover {
    border: 1px solid $brand-primary;
  }

  &.active {
    background-color: #D9D9D9;
    border: 1px solid $brand-primary;

    /*&:hover {
      border: 1px solid transparent;
    }*/

    .device-info {
    	font-weight: bold;
    }
  }

  .icon {
    background-color: lightgray;
    color: grey;
    padding: .8rem;
    border-top-left-radius: 0.6rem;
    border-bottom-left-radius: 0.6rem;

    &.poor {
      background-color: #FEE2E2;
      color: #DC2626;
    }

    &.average {
      background-color: #FEF3C7;
      color: #D97706;
    }

    &.good {
      background-color: #DCFCE7;
      color: #16A34A;
    }

    svg {
      vertical-align: middle;
    }
  }

  .device-info {
    font-size: initial;
    padding-right: 10px;

    #device-name {
      font-size: small;
    }
  }
}

.no-devices {
  display: flex;
  align-items: center;
  font-weight: bold;
  justify-content: center;

  img {
    max-width: 50px;
    max-height: 50px;
  }

}
